values
  ('l1', null, true, 'Sunny private room off Clifton Ave', '3412 Clifton Ave', 'Clifton', 39.1418, -84.5212, 575, false, 60, '2027-01-01', '2027-04-30', 3, true, 'room', 'sublease', 'Big bedroom with a south-facing window in a quiet three-bedroom. Two easygoing roommates, shared kitchen and living room. I''m on co-op in Chicago for spring.', array['laundry', 'wifi', 'bed', 'parking']::text[], 100, 50, '{"roommates":2,"cleanliness":4,"noise":2,"social":2,"guests":2,"sleep":3,"approachability":4,"smokeFree":true,"cat":false,"dog":false}'::jsonb, null, true, array['/photos/bedroom-4.jpg', '/photos/living-2.jpg', '/photos/kitchen-6.jpg']::text[], '{}'::text[], 'Maya R.', 'Mechanical Eng · 4th year', now() - interval '1 days'),
  ('l2', null, true, 'Furnished studio steps from McMicken', '2 W McMillan St', 'Uptown', 39.1325, -84.5167, 895, true, 0, '2027-01-01', '2027-08-14', 0, true, 'whole', 'assignment', 'A tidy studio you can walk to class from. Utilities and internet are covered. Spring through summer, so you can stay through a co-op swap.', array['utilities', 'elevator', 'security', 'gym']::text[], 200, 100, null, '{"group":"Campus Edge Properties","rating":4.1,"count":286}'::jsonb, true, array['/photos/living-3.jpg', '/photos/kitchen-1.jpg', '/photos/bedroom-5.jpg']::text[], '{}'::text[], 'Jordan K.', 'Architecture · 5th year', now() - interval '3 days'),
  ('l3', null, true, 'Two-bedroom, whole unit in Corryville', '2810 Vine St', 'Corryville', 39.136, -84.5103, 1350, false, 120, '2027-05-01', '2027-08-15', 2, false, 'whole', 'sublease', 'Bright second-floor two-bedroom for the summer. Unfurnished, so bring your own stuff or split it with a friend. Five minutes from the medical campus.', array['dishwasher', 'ac', 'parking']::text[], 0, 0, null, null, true, array['/photos/living-4.jpg', '/photos/bedroom-6.jpg', '/photos/kitchen-2.jpg']::text[], '{}'::text[], 'Priya S.', 'Nursing · 3rd year', now() - interval '6 days'),
  ('l4', null, true, 'Brick loft one-bedroom in OTR', '1415 Race St', 'Over-the-Rhine', 39.1117, -84.5155, 1425, false, 90, '2027-01-03', '2027-08-31', 1, true, 'whole', 'assignment', 'Exposed brick, tall windows and a real kitchen. Take over my lease through August. Fully furnished, and the bus to campus stops at the corner.', array['laundry', 'bike', 'rooftop']::text[], 250, 50, null, '{"group":"Vine & Race Lofts","rating":4.5,"count":132}'::jsonb, true, array['/photos/living-5.jpg', '/photos/kitchen-3.jpg', '/photos/bedroom-1.jpg']::text[], '{}'::text[], 'Eli T.', 'Marketing · 4th year', now() - interval '2 days'),
  ('l5', null, true, 'Room in a five-bedroom Uptown house', '2701 Calhoun St', 'Uptown', 39.13, -84.519, 520, false, 70, '2027-08-15', '2027-12-31', 5, false, 'room', 'sublease', 'Lively house with a big porch and a back yard. Room is unfurnished, with a closet and a built-in shelf. Fall term, a few minutes'' walk from the stadium.', array['outdoor', 'laundry']::text[], 0, 0, '{"roommates":4,"cleanliness":2,"noise":4,"social":4,"guests":3,"sleep":4,"approachability":5,"smokeFree":false,"cat":false,"dog":true}'::jsonb, null, true, array['/photos/bedroom-2.jpg', '/photos/living-6.jpg', '/photos/kitchen-4.jpg']::text[], '{}'::text[], 'Sam L.', 'IT · 3rd year', now() - interval '9 days'),
  ('l6', null, true, 'Quiet furnished one-bedroom in Clifton', '3305 Whitfield Ave', 'Clifton', 39.1405, -84.528, 950, true, 0, '2027-05-02', '2027-08-14', 1, true, 'whole', 'sublease', 'Peaceful one-bedroom in a small building with a leafy courtyard. Utilities are included in the rent. Ideal for a summer co-op or research position.', array['utilities', 'outdoor', 'laundry', 'pets']::text[], 0, 0, null, '{"group":"Whitfield Courtyard","rating":4.6,"count":58}'::jsonb, true, array['/photos/living-1.jpg', '/photos/bedroom-3.jpg', '/photos/kitchen-5.jpg']::text[], '{}'::text[], 'Noah B.', 'Chemistry · 4th year', now() - interval '1 days'),
  ('l7', null, true, 'OTR room with rooftop access', '118 W Elder St', 'Over-the-Rhine', 39.1137, -84.5144, 750, true, 0, '2027-08-15', '2027-12-20', 2, true, 'room', 'sublease', 'Furnished room in a two-bedroom with one friendly roommate. Rooftop deck, and Findlay Market is two blocks away. Utilities are included.', array['utilities', 'rooftop', 'bed', 'dishwasher']::text[], 0, 0, '{"roommates":1,"cleanliness":5,"noise":2,"social":2,"guests":2,"sleep":2,"approachability":3,"smokeFree":true,"cat":true,"dog":false}'::jsonb, null, true, array['/photos/bedroom-4.jpg', '/photos/kitchen-6.jpg', '/photos/living-2.jpg']::text[], '{}'::text[], 'Aaliyah M.', 'Design · 3rd year', now() - interval '4 days'),
  ('l8', null, true, 'Furnished room in a Corryville three-bedroom', '2915 Jefferson Ave', 'Corryville', 39.133, -84.512, 610, false, 55, '2027-01-02', '2027-04-30', 3, true, 'room', 'sublease', 'Comfortable room with a full bed and desk, in a house with two quiet roommates. A short walk to the Rec Center and Short Vine.', array['bed', 'laundry', 'wifi']::text[], 0, 0, '{"roommates":2,"cleanliness":3,"noise":3,"social":3,"guests":3,"sleep":3,"approachability":4,"smokeFree":true,"cat":false,"dog":false}'::jsonb, null, true, array['/photos/bedroom-5.jpg', '/photos/living-3.jpg', '/photos/kitchen-1.jpg']::text[], '{}'::text[], 'Tyler W.', 'Finance · 4th year', now() - interval '12 days'),
  ('l9', null, true, 'Two-bedroom near the Rec Center', '2640 Stratford Ave', 'Uptown', 39.1292, -84.5175, 1100, false, 100, '2027-01-01', '2027-04-30', 2, false, 'whole', 'relet', 'Spacious unfurnished two-bedroom for spring semester. The landlord is fine with a short re-let and will draw up the paperwork.', array['dishwasher', 'ac']::text[], 150, 0, null, null, true, array['/photos/living-4.jpg', '/photos/kitchen-2.jpg', '/photos/bedroom-6.jpg']::text[], '{}'::text[], 'Riley C.', 'Biology · 4th year', now() - interval '2 days'),
  ('l10', null, true, 'Clifton studio with a parking spot', '3250 Ludlow Ave', 'Clifton', 39.1412, -84.5185, 780, true, 0, '2027-05-01', '2027-08-31', 0, false, 'whole', 'sublease', 'Studio above a quiet cafe on Ludlow. Includes an assigned parking spot, which is rare around here. Utilities are included.', array['utilities', 'parking']::text[], 0, 0, null, null, true, array['/photos/living-5.jpg', '/photos/bedroom-1.jpg', '/photos/kitchen-3.jpg']::text[], '{}'::text[], 'Devon H.', 'Civil Eng · 5th year', now() - interval '5 days'),
  ('l11', null, true, 'Furnished summer room, four-bedroom house', '2511 Ohio Ave', 'Uptown', 39.1318, -84.5182, 480, false, 60, '2027-05-03', '2027-08-13', 4, true, 'room', 'sublease', 'Cheapest room on the block for the summer. Furnished, window AC, and a relaxed house with three roommates who are mostly out on co-op.', array['ac', 'bed', 'outdoor']::text[], 0, 0, '{"roommates":3,"cleanliness":3,"noise":4,"social":3,"guests":4,"sleep":5,"approachability":4,"smokeFree":true,"cat":false,"dog":false}'::jsonb, null, true, array['/photos/bedroom-2.jpg', '/photos/living-6.jpg', '/photos/kitchen-4.jpg']::text[], '{}'::text[], 'Chris P.', 'Computer Sci · 3rd year', now() - interval '0 days'),
  ('l12', null, true, 'One-bedroom on Short Vine', '2706 Short Vine', 'Corryville', 39.135, -84.5105, 820, false, 80, '2027-08-16', '2027-12-17', 1, true, 'whole', 'assignment', 'Furnished one-bedroom with a walkable location: coffee, groceries and the bus line are all close. The lease lines up exactly with the fall term.', array['bed', 'dishwasher', 'bike']::text[], 175, 50, null, null, true, array['/photos/living-1.jpg', '/photos/kitchen-5.jpg', '/photos/bedroom-3.jpg']::text[], '{}'::text[], 'Hana Y.', 'Pharmacy · 3rd year', now() - interval '7 days'),
  ('l13', null, true, 'Two-bedroom, whole unit in OTR', '1520 Vine St', 'Over-the-Rhine', 39.1128, -84.5149, 1480, false, 110, '2027-01-04', '2027-04-30', 2, true, 'whole', 'sublease', 'Furnished two-bedroom in a renovated building. Great for two co-op students splitting the rent. Streetcar stop is a block away.', array['laundry', 'bed', 'elevator', 'gym']::text[], 300, 100, null, '{"group":"Rhine Residences","rating":3.9,"count":87}'::jsonb, true, array['/photos/living-2.jpg', '/photos/bedroom-4.jpg', '/photos/kitchen-6.jpg']::text[], '{}'::text[], 'Marcus D.', 'Business · 5th year', now() - interval '3 days'),
  ('l14', null, true, 'Room in a big Clifton house', '3401 McAlpin Ave', 'Clifton', 39.142, -84.5175, 495, false, 65, '2027-08-16', '2027-12-31', 6, false, 'room', 'sublease', 'Large room in a six-bedroom house with a huge kitchen. Unfurnished, but there''s a shared living room with plenty of space. Fall term.', array['laundry', 'kitchen', 'outdoor']::text[], 0, 0, '{"roommates":5,"cleanliness":3,"noise":4,"social":4,"guests":3,"sleep":4,"approachability":4,"smokeFree":true,"cat":true,"dog":false}'::jsonb, null, true, array['/photos/bedroom-5.jpg', '/photos/kitchen-1.jpg', '/photos/living-3.jpg']::text[], '{}'::text[], 'Grace N.', 'Education · 4th year', now() - interval '15 days'),
  ('l15', null, true, 'Furnished three-bedroom, whole unit', '2800 Clifton Ave', 'Uptown', 39.134, -84.5185, 1590, false, 140, '2027-05-01', '2027-08-20', 3, true, 'whole', 'sublease', 'Take the whole place for the summer, perfect for a group of three. Fully furnished with a big living room, and right across from campus.', array['bed', 'ac', 'dishwasher', 'laundry']::text[], 125, 50, null, '{"group":"Clifton Court Apartments","rating":4.2,"count":410}'::jsonb, true, array['/photos/living-4.jpg', '/photos/kitchen-2.jpg', '/photos/bedroom-6.jpg']::text[], '{}'::text[], 'Owen F.', 'Engineering · 4th year', now() - interval '1 days'),
  ('l16', null, true, 'Cheap room in a Norwood three-bedroom', '4112 Smith Rd', 'Norwood', 39.159, -84.454, 425, false, 55, '2027-01-02', '2027-04-30', 3, false, 'room', 'sublease', 'A bit farther out, but it''s the cheapest room on the list and there''s free parking out front. The bus runs to campus every 15 minutes. Quiet house, easygoing roommates.', array['parking', 'laundry', 'outdoor']::text[], 0, 0, '{"roommates":2,"cleanliness":4,"noise":2,"social":2,"guests":1,"sleep":2,"approachability":3,"smokeFree":true,"cat":false,"dog":false}'::jsonb, null, true, array['/photos/bedroom-3.jpg', '/photos/living-6.jpg', '/photos/kitchen-3.jpg']::text[], '{}'::text[], 'Isaiah J.', 'Accounting · 4th year', now() - interval '2 days'),
  ('l17', null, true, 'Room in a Northside house with a porch', '4175 Hamilton Ave', 'Northside', 39.1745, -84.544, 480, false, 65, '2027-05-03', '2027-08-13', 4, true, 'room', 'sublease', 'Summer room in a lively Northside house, steps from the coffee shops and live music. Furnished with a bed and desk. Bring a bike or take the bus to campus.', array['bed', 'wifi', 'bike', 'outdoor', 'pets']::text[], 75, 50, '{"roommates":3,"cleanliness":2,"noise":4,"social":4,"guests":3,"sleep":5,"approachability":5,"smokeFree":false,"cat":true,"dog":true}'::jsonb, null, true, array['/photos/bedroom-5.jpg', '/photos/kitchen-6.jpg', '/photos/living-1.jpg']::text[], '{}'::text[], 'Luca V.', 'Music Ed · 3rd year', now() - interval '5 days'),
  ('l18', null, true, 'Bright studio in Oakley', '3200 Madison Rd', 'Oakley', 39.1517, -84.4351, 700, true, 0, '2027-08-16', '2027-12-17', 0, true, 'whole', 'assignment', 'A tidy furnished studio with utilities included and a car-friendly lot. About a 15 minute drive to campus. Lease lines up with the fall term.', array['utilities', 'bed', 'parking', 'ac', 'laundry']::text[], 150, 100, null, '{"group":"Madison Row Living","rating":4,"count":203}'::jsonb, true, array['/photos/living-2.jpg', '/photos/bedroom-1.jpg', '/photos/kitchen-2.jpg']::text[], '{}'::text[], 'Zoe A.', 'Biology · 4th year', now() - interval '1 days'),
  ('l19', null, true, 'Two-bedroom in Blue Ash with a garage', '9500 Kenwood Rd', 'Blue Ash', 39.232, -84.38, 1050, false, 110, '2027-05-01', '2027-08-20', 2, false, 'whole', 'sublease', 'Roomy two-bedroom for a summer co-op nearby, with a garage and a patio. It is a drive to campus, so this one is best if you have a car.', array['parking', 'dishwasher', 'ac', 'laundry', 'outdoor']::text[], 0, 0, null, null, true, array['/photos/living-4.jpg', '/photos/kitchen-5.jpg', '/photos/bedroom-6.jpg']::text[], '{}'::text[], 'Ethan G.', 'Mechanical Eng · 5th year', now() - interval '8 days'),
  ('l20', null, true, 'Whole two-bedroom in Florence, KY', '7350 Turfway Rd', 'Florence, KY', 39.0095, -84.6411, 780, false, 95, '2027-08-16', '2027-12-17', 2, false, 'whole', 'relet', 'Low rent across the river for the fall term. You''ll want a car, and there is plenty of free parking. A roomy kitchen and in-unit laundry.', array['parking', 'laundry', 'dishwasher', 'ac', 'kitchen']::text[], 100, 0, null, null, true, array['/photos/living-3.jpg', '/photos/kitchen-1.jpg', '/photos/bedroom-4.jpg']::text[], '{}'::text[], 'Hannah O.', 'Marketing · 4th year', now() - interval '3 days');
